mapper.select:
select id, order_id, device_id, protocol, reference_type, external_reference, created_at
from pep_domain.order_external_reference
where device_id = #{deviceId}
  and protocol = #{protocol}
  and reference_type = #{referenceType}
  and external_reference = #{externalReference}

select id, order_id, device_id, protocol, reference_type, external_reference, created_at
from pep_domain.order_external_reference
where order_id = #{orderId}
  and protocol = #{protocol}
  and reference_type = #{referenceType}
